import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Mesh, PlaneGeometry, Group } = ctx.THREE;

  // Create group for the badge
  const group = new Group();
  group.position.set(1.25, 0.7, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Geometry for the badge plane
  const geometry = new PlaneGeometry(0.8, 0.28);

  // Material with texture
  const material = new MeshBasicNodeMaterial({
    color: 0xff2a38, // accent red
    emissive: 0xff2a38,
    emissiveIntensity: 0.4
  });

  // Load the ceramic grain texture
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    material.map = texture;
    material.needsUpdate = true;
  });

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Store interaction state
  let isPressed = false;
  let hoverTimeline = null;
  let pressTimeline = null;

  // Hover handlers
  const onHover = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(group.position, {
      y: group.position.y + 0.15,
      duration: 0.5,
      ease: 'power3.out',
      overwrite: 'auto'
    });
  };

  const onHoverOut = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(group.position, {
      y: 0.7,
      duration: 0.5,
      ease: 'power3.out',
      overwrite: 'auto'
    });
  };

  // Click handlers
  const onClick = () => {
    isPressed = true;

    if (pressTimeline) pressTimeline.kill();
    pressTimeline = gsap.to(group.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out',
      onComplete: () => {
        gsap.to(group.scale, {
          x: 1,
          y: 1,
          duration: 0.3,
          ease: 'back.out'
        });
        isPressed = false;
      }
    });

    // Emit navigation event
    ctx.emit('navigate', { to: 'hub-pricing' });
  };

  // Attach handlers
  group.userData.handlers = {
    onHover,
    onHoverOut,
    onClick
  };

  // Cleanup function
  group.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTimeline) pressTimeline.kill();
    geometry.dispose();
    material.dispose();
  };

  return group;
}
